FIELDS = {'FlexRearAntenna': (False, 'Rear VTX antenna mount', 'One-piece TPU mount on the rearmost upper standoffs.'), 'FlexAntennaConnector': ('u.FL', 'Antenna connection', 'SMA/RP-SMA: flat bulkhead tab for a pigtail secured by its nut and washer. u.FL/MMCX: tubular holder for the measured antenna stem, not the PCB connector.', ('SMA', 'RP-SMA', 'u.FL', 'MMCX')), 'FlexAntennaCount': ('1 antenna', 'Antenna count', 'One rear antenna or two with symmetric outward yaw of 30 degrees each. Elevation uses Antenna tilt.', ('1 antenna', '2 antennas')), 'FlexAntennaBarShape': ('Curved', 'Connecting bar shape', 'Broad rounded connecting bar, triangular brace or filled rectangular platform in top view.', ('Curved', 'Triangle', 'Rectangle')), 'FlexAntennaReach': (20.0, 'Rearward reach', 'Distance from the rear standoff row to the connecting bar apex. Holder fore/aft offset moves the sleeves independently.'), 'FlexAntennaGripHeight': (8.0, 'Standoff grip height', 'Requested sleeve height. The side-guard rear grip adjusts to support the antenna grip directly. Available height caps the request while retaining at least 4 mm of guard bearing.'), 'FlexAntennaGripWall': (3.0, 'Standoff grip wall', 'Radial sleeve wall thickness. Only grip rings may extend outside plate or guard width.'), 'FlexAntennaFit': (0.2, 'Standoff fit allowance', 'Diametral standoff clearance. Tune with a test print.'), 'FlexAntennaBarWidth': (6.0, 'Connecting bar width', 'Fore/aft rib thickness. Minimum 4 mm.'), 'FlexAntennaBore': (0.0, 'Antenna bore diameter', 'Zero uses 6.5 mm for SMA/RP-SMA, 4 mm u.FL stems or 3 mm MMCX stems. Override using measured hardware and print allowance.'), 'FlexAntennaSocketWall': (1.2, 'Antenna holder wall', 'Radial tube wall for u.FL/MMCX. For SMA/RP-SMA it enlarges the tab when the hole needs more surrounding stock; the tab is at least 12 mm wide.'), 'FlexAntennaSocketLength': (0.0, 'Antenna holder length', 'u.FL/MMCX sleeve length along the antenna axis; zero uses 6 mm. Extends outward from a fixed root. Retained but inactive for SMA/RP-SMA, which use bulkhead tab thickness.'), 'FlexAntennaSpacing': (14.0, 'Dual antenna spacing', 'Distance between holder centres; active for two antennas. Must fit the rear width.'), 'FlexAntennaTilt': (60.0, 'Antenna tilt', 'Elevation above horizontal: 0 degrees rearward and level, 90 degrees upright. Default 60 degrees is 30 degrees from vertical; dual outward yaw remains 30 degrees per side.'), 'FlexAntennaStandoffBore': (0.0, 'Standoff hole diameter', 'Direct finished hole diameter. Zero uses standoff diameter plus fit allowance. A nonzero value overrides that allowance; must be at least the modeled standoff diameter.'), 'FlexAntennaHolderOffset': (0.0, 'Holder fore/aft offset', 'Move the antenna sleeves independently of the connecting bar. Positive moves rearward/out; negative moves toward the frame. Actual plate and guard collisions remain blocked.'), 'FlexAntennaBulkheadThickness': (2.4, 'SMA bulkhead tab thickness', 'Thickness clamped between the pigtail shoulder and its nut/washer. SMA and RP-SMA only; 2 to 5 mm. Verify enough thread remains for the nut and antenna.'), 'FlexAntennaHolderStyle': ('Closed tube', 'Stem holder style', 'Closed tube slides over the stem. Side-entry clip opens toward frame front through the full axial thickness at the clip, without an added rear brace. At zero tilt, a horizontal rearward stem uses upward radial entry because front is along its axis. u.FL/MMCX only.', ('Closed tube', 'Side-entry clip')), 'FlexAntennaRetainingLip': (0.4, 'Stem retaining lip', 'Per-side retention for the side-entry opening. Opening width equals stem bore minus twice this lip. Tune to TPU and the measured stem.')}

